function terminalSafe(value, maxBytes = 500) {
  const p = [];
  const sizes = [];
  let bytes = 0;
  let truncated = false;
  for (const character of String(value)) {
    let piece = character;
    if (UNSAFE_TERMINAL.test(character)) {
      const code = character.codePointAt(0);
      piece = code <= 0xff
        ? "\\x" + code.toString(16).padStart(2, "0")
        : "\\u" + code.toString(16).padStart(4, "0");
    }
    const size = Buffer.byteLength(piece, "utf8");
    if (bytes + size > maxBytes) { truncated = true; break; }
    p.push(piece);
    sizes.push(size);
    bytes += size;
  }
  if (!truncated) return p.join("");
  const markerBytes = Buffer.byteLength(TRUNCATION_MARKER, "utf8");
  while (p.length && bytes + markerBytes > maxBytes) {
    p.pop();
    bytes -= sizes.pop();
  }
  return p.join("") + TRUNCATION_MARKER;
}
